def transform(grid):
    shapes=[]
    seen=set()
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==0 or (r,c) in seen: continue
            pts=[]; stack=[(r,c)]; seen.add((r,c))
            while stack:
                a,b=stack.pop(); pts.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<len(grid) and 0<=y<len(row) and (x,y) not in seen and grid[x][y]==v:
                        seen.add((x,y)); stack.append((x,y))
            shapes.append(pts)
    pts=min(shapes,key=len)
    a=min(x for x,y in pts); b=max(x for x,y in pts)
    c=min(y for x,y in pts); d=max(y for x,y in pts)
    return [row[c:d+1] for row in grid[a:b+1]]

